    let period=false,periodRows=0;const periodLines=[];for(let i=0;i<lines.length;i++){if(/^(?:period of (?:policy|insurance|cover)|policy period|period of risk|policy effective)/i.test(lines[i])){period=true;periodRows=0;for(let j=Math.max(0,i-2);j<i;j++)if(/^from\b/i.test(lines[j]))periodLines.push(j)}else if(period&&(/^(?:your |coverages|previous |premium|nominee|posp|receipt|invoice|optional cover|address|intermediary)/i.test(lines[i])||++periodRows>30))period=false;if(period)periodLines.push(i)}
    const periodSet=new Set(periodLines);
    for(const [key,label] of [['startDate','from'],['expiryDate','to']])if(!fields[key]){
      const candidates=[];for(const i of periodLines){const match=lines[i].match(new RegExp('(?:^|\\s)'+label+'(?:\\s|[:：]|$)(.*)$','i'));if(!match)continue;let raw=match[1].split(label==='from'?/\bto\b/i:/\bfrom\b/i)[0];for(let j=i+1;j<Math.min(i+5,lines.length)&&periodSet.has(j)&&!date(raw)&&!labelPattern.test(lines[j])&&!/\\b(?:from|to)\\b/i.test(lines[j]);j++)raw+=' '+lines[j];const dates=[...new Set((raw.match(datePattern)||[]).map(date).filter(Boolean))];if(dates.length===1)candidates.push(dates[0]);else if(dates.length>1)candidates.push(...dates)}
      const unique=[...new Set(candidates)];if(unique.length===1){fields[key]=unique[0];evidence[key]='Policy period '+label}
    }
